// This file intentionally contains ONLY fictional lead examples.
// .invalid is an IANA-reserved test domain, not a reachable mailbox.
const fixtures = [
  {
    case_id: '01_valid', event_id: 'lead-001', name: 'Avery Example',
    email: '  user@example.com  ', phone: '+1234567890',
    source: 'sample-form', utm_source: 'linkedin', utm_medium: 'social',
    utm_campaign: 'np04-preflight'
  },
  {
    case_id: '02_phone_only', event_id: 'lead-002', name: 'Jordan Test',
    email: '', phone: '+1234567890', source: 'sample-form'
  },
  {
    case_id: '03_no_contact', event_id: 'lead-003', name: 'Morgan Demo',
    email: '', phone: '', source: 'sample-form'
  },
  {
    case_id: '04_bad_email', event_id: 'lead-004', name: 'Casey Example',
    email: 'not-an-email', phone: '+1234567890', source: 'sample-form'
  },
  {
    case_id: '05_repeat_event', event_id: 'lead-001', name: 'Avery Replay',
    email: 'user@example.com', phone: '', source: 'sample-form'
  },
  {
    case_id: '06_repeat_email', event_id: 'lead-006', name: 'Avery Two',
    email: 'user@example.com', phone: '', source: 'sample-form'
  },
  {
    case_id: '07_missing_event', event_id: '', name: 'Taylor Example',
    email: 'user@example.com', phone: '', source: 'sample-form'
  },
  {
    case_id: '08_structured_field', event_id: 'lead-008', name: 'Morgan Bad',
    email: { value: 'user@example.com' }, phone: ['+1234567890'],
    source: 'sample-form'
  },
  {
    case_id: '09_bad_utm_safe', event_id: 'lead-009', name: 'Zee Example',
    email: 'user@example.com', phone: '', source: 'sample-form',
    utm_source: { unexpected: true }, utm_medium: 'social'
  }
];
return fixtures.map(fixture => ({ json: fixture }));

// Import-only educational preflight, no credentials, CRM, network, or persistence.
// Repeated event IDs / emails are detected only WITHIN the current batch/run.
const seenEventIds = new Set();
const seenEmails = new Set();

function readText(value, maxLength) {
  if (value === null || value === undefined) return { value: '', invalid: false };
  if (typeof value !== 'string') return { value: '', invalid: true };
  const cleaned = value.replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
  if (cleaned.length > maxLength) return { value: cleaned.slice(0, maxLength), invalid: true };
  return { value: cleaned, invalid: false };
}

function statusResult(caseId, normalized, status, reasons) {
  return { json: {
    case_id: caseId, status, reason_codes: reasons,
    normalized_fields: normalized,
    diagnostic_scope: 'SYNTHETIC_OFFLINE_BATCH_ONLY'
  } };
}

const results = [];
for (const item of $input.all()) {
  const raw = item && item.json;
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    results.push(statusResult('invalid-shape', {}, 'HOLD_MALFORMED_INPUT', ['PAYLOAD_NOT_OBJECT']));
    continue;
  }
  const caseIdField = readText(raw.case_id, 60);
  const caseId = caseIdField.invalid ? 'invalid-case-id' : (caseIdField.value || 'unnamed-sample');
  const event = readText(raw.event_id, 64);
  const name = readText(raw.name, 120);
  const email = readText(raw.email, 254);
  const phone = readText(raw.phone, 30);
  const source = readText(raw.source, 80);
  const reasons = [];
  const utms = {};
  for (const key of ['utm_source', 'utm_medium', 'utm_campaign']) {
    const value = readText(raw[key], 100);
    utms[key] = value.invalid ? '' : value.value;
    if (value.invalid) reasons.push('INVALID_' + key.toUpperCase() + '_IGNORED');
  }
  if (!source.value) reasons.push('MISSING_SOURCE');
  if (!name.value) reasons.push('MISSING_NAME');
  const eventId = event.value;
  const normalizedEmail = email.value.toLowerCase();
  const emailPresent = normalizedEmail.length > 0;
  const emailValid = emailPresent && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizedEmail);
  const rawPhone = phone.value.replace(/[\s().-]/g, '');
  const phoneValid = rawPhone.length > 0 && /^\+?[0-9]{7,15}$/.test(rawPhone);
  if (phone.value && !phoneValid) reasons.push('INVALID_PHONE_IGNORED');
  const normalized = {
    event_id: eventId, name: name.value,
    email: emailPresent ? normalizedEmail : '',
    phone: phoneValid ? rawPhone : '',
    source: source.value || 'unspecified',
    utm_source: utms.utm_source,
    utm_medium: utms.utm_medium,
    utm_campaign: utms.utm_campaign
  };
  const malformed = name.invalid || email.invalid || phone.invalid || source.invalid;
  const validEvent = !event.invalid && /^[A-Za-z0-9][A-Za-z0-9_.:-]{2,63}$/.test(eventId);
  const repeatedId = validEvent && seenEventIds.has(eventId);
  const repeatedEmail = emailValid && seenEmails.has(normalizedEmail);
  let status;
  if (malformed) {
    status = 'HOLD_MALFORMED_INPUT';
    reasons.unshift('STRUCTURED_OR_OVERSIZED_FIELD');
  } else if (!validEvent) {
    status = 'HOLD_INVALID_EVENT';
    reasons.unshift('MISSING_OR_INVALID_EVENT_ID');
  } else if (repeatedId) {
    status = 'REVIEW_DUPLICATE_IN_BATCH';
    reasons.unshift('EVENT_ID_REPEATED_IN_THIS_RUN');
  } else if (emailPresent && !emailValid) {
    status = 'HOLD_BAD_EMAIL';
    reasons.unshift('EMAIL_FORMAT_INVALID');
  } else if (!emailPresent && !phoneValid) {
    status = 'HOLD_MISSING_CONTACT';
    reasons.unshift('NO_USABLE_CONTACT_ROUTE');
  } else if (repeatedEmail) {
    status = 'REVIEW_SAME_EMAIL_IN_BATCH';
    reasons.unshift('EMAIL_SEEN_IN_THIS_RUN');
  } else if (!emailPresent && phoneValid) {
    status = 'REVIEW_PHONE_ONLY';
    reasons.unshift('PHONE_ONLY_MANUAL_REVIEW');
  } else {
    status = 'READY_FOR_REVIEW';
    reasons.unshift('PREFLIGHT_PASSED_NOT_CRM_WRITE');
  }
  if (validEvent && !repeatedId) seenEventIds.add(eventId);
  if (emailValid && !repeatedId) seenEmails.add(normalizedEmail);
  results.push(statusResult(caseId, normalized, status, reasons));
}
return results;

return $input.all().map(item => ({
  json: {
    ...(item.json || {}),
    status: 'HOLD_MALFORMED_INPUT',
    route_decision: 'FALLBACK_MANUAL_REVIEW',
    reason_codes: [
      ... (Array.isArray(item.json?.reason_codes) ? item.json.reason_codes : []),
      'UNEXPECTED_ROUTING_STATUS'
    ]
  }
}));
